// AI Agent Tool: read_file
const filePath = $input.item.json.filePath;

// Get site info
let site;
try {
  site = $('Merge Files').item.json.site;
} catch (e) {
  site = $input.item.json.site || {};
}

const owner = site.owner;
const repo = site.repo;
const branch = site.default_branch || 'main';

if (!owner || !repo || !filePath) {
  return {
    json: {
      success: false,
      error: 'Missing required parameters (owner/repo/filePath)'
    }
  };
}

// Build GitHub file URL
const url = `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}?ref=${branch}`;

try {
  // Fetch file contents
  const response = await fetch(url, {
    headers: {
      'Authorization': `Bearer ${$env.GITHUB_TOKEN}`,
      'Accept': 'application/vnd.github.raw',
      'X-GitHub-Api-Version': '2022-11-28'
    }
  });

  const content = await response.text();

  // Add line numbers
  const lines = content.split('\n');
  const numberedContent = lines.map((line, i) => `${i + 1}\t${line}`).join('\n');

  return {
    json: {
      success: true,
      filePath: filePath,
      content: numberedContent,
      rawContent: content,
      lines: lines.length,
      message: `Successfully read ${filePath} (${lines.length} lines)`
    }
  };
} catch (error) {
  return {
    json: {
      success: false,
      error: error.message,
      filePath: filePath
    }
  };
}
